/// Looks a runeword up by name, ignoring ASCII case and apostrophes ([`crate::names::same_name`]:
/// `"steel"`, `"Ancients' Pledge"` match): the `BiS` piece strings in the config are user-typed. Disambiguated
/// upstream names (`"Hustle (armor)"`, `"Hustle (weapon)"`) also match their bare
/// form, since that is what the game shows.
#[must_use]
pub fn lookup(name: &str) -> Option<&'static Runeword> {
    RUNEWORDS.iter().find(|w| {
        crate::names::same_name(w.name, name)
            || w.name
                .split_once(" (")
                .is_some_and(|(bare, _)| crate::names::same_name(bare, name))
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lookup_matches_any_case() {
        assert!(lookup("steel").is_some(), "lowercase must match");
        assert!(lookup("STEEL").is_some(), "uppercase must match");
        assert!(lookup("Steel").is_some(), "the display name must match");
        assert!(lookup("Crafted Rare").is_none(), "non-runewords must not match");
        assert!(
            lookup("Ancients' Pledge").is_some(),
            "the builds' apostrophe must match"
        );
    }

    #[test]
    fn ancients_pledge_runes_are_in_socket_order() {
        let rw = lookup("Ancient's Pledge");
        assert!(rw.is_some(), "Ancient's Pledge must be in the table");
        if let Some(rw) = rw {
            assert_eq!(rw.runes, ["Ral", "Ort", "Tal"].as_slice(), "socket order");
            assert!(rw.bases.contains(&"shields"), "bases must contain shields");
        }
    }

    #[test]
    fn every_runeword_has_at_least_one_rune_and_base() {
        assert!(
            RUNEWORDS
                .iter()
                .all(|w| !w.runes.is_empty() && !w.bases.is_empty())
        );
    }

    #[test]
    fn disambiguated_names_match_their_bare_form() {
        assert!(
            lookup("Hustle").is_some(),
            "the game shows Hustle without a suffix"
        );
    }

    #[test]
    fn every_rune_is_a_d2_rune_name() {
        assert!(
            RUNEWORDS
                .iter()
                .all(|w| w.runes.iter().all(|r| RUNE_NAMES.contains(r)))
        );
    }
}
